Add-Type @"
using System; using System.Text; using System.Collections.Generic; using System.Runtime.InteropServices;
public class W4 { public delegate bool P(IntPtr h, IntPtr l);
[DllImport("user32.dll")] static extern bool EnumWindows(P p, IntPtr l);
[DllImport("user32.dll")] static extern int GetWindowText(IntPtr h, StringBuilder s, int n);
[DllImport("user32.dll")] static extern bool IsWindowVisible(IntPtr h);
[DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
public static List<string> List(uint[] ids) { var o = new List<string>(); EnumWindows((h,l) => { uint p; GetWindowThreadProcessId(h, out p); if (Array.IndexOf(ids,p) >= 0) { var sb = new StringBuilder(200); GetWindowText(h, sb, 200); if (sb.ToString().StartsWith("dotpals")) o.Add(sb + " visible=" + IsWindowVisible(h)); } return true; }, IntPtr.Zero); return o; } }
"@
[W4]::List([uint32[]](Get-Process electron | ForEach-Object Id))
